contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 cash, uint256 tenor1, uint256 tenor2) public view {
        require(tenor1 != 0 && tenor1 < tenor2);
        // Swap fee scales with tenor: fee(cash, t) = cash * (mulDivUp(swapFeeAPR, t, YEAR)) / PERCENT,
        // which is non-decreasing in t for any fixed swapFeeAPR >= 0.
        uint256 fee1 = c.getSwapFee(cash, tenor1);
        uint256 fee2 = c.getSwapFee(cash, tenor2);
        assert(fee2 >= fee1);
    }
}

