contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 cash, uint256 tenor) public {
        // fee configuration is read through the public view
        InitializeFeeConfigParams memory f = c.feeConfig();

        if (tenor == 0) {
            bool reverted;
            uint256 fee;
            try c.getSwapFee(cash, tenor) returns (uint256 r) {
                reverted = false;
                fee = r;
            } catch {
                reverted = true;
            }
            assert(reverted && fee == 0);
        } else {
            uint256 fee = c.getSwapFee(cash, tenor);
            uint256 swapFeePercent = Math_1.mulDivUp(f.swapFeeAPR, tenor, YEAR);
            uint256 expected = Math_1.mulDivUp(cash, swapFeePercent, PERCENT);
            assert(fee == expected);
        }
    }
}

