    constructor(C _c) { c = _c; }

    function run(uint256 cash1, uint256 cash2, uint256 tenor) public {
        require(tenor >= 1 && tenor <= 365 days);
        require(cash1 <= 10 ** 24 && cash2 <= 10 ** 24);
        InitializeFeeConfigParams memory f = c.feeConfig();
        require(f.swapFeeAPR <= PERCENT);

        uint256 fee1 = c.getSwapFee(cash1, tenor);
        uint256 fee2 = c.getSwapFee(cash2, tenor);
        uint256 fee12 = c.getSwapFee(cash1 + cash2, tenor);

        uint256 feePercent = (f.swapFeeAPR * tenor) / YEAR;
        uint256 expected1 = (cash1 * feePercent + PERCENT - 1) / PERCENT;

        assert(fee12 >= fee1 + fee2 && fee1 == expected1);
    }
}

